mask={(r,c) for r in range(9) for c in range(20) if grid[r][c]==1}
# template shapes sizes. define identities; rotations optional. D etc footprints rectangles
shapes=[('checker4x6',4,6,1),('rect5x3',5,3,1),('rect5x2',5,2,1),('rect4x2',4,2,1),('rect2x3',2,3,1),('rect2x2',2,2,1),('line5',5,1,1),('zero',1,1,2)]

def placements_for(shape,allowrot):
 name,h,w,n=shape
 dims={(h,w)}
 if allowrot: dims.add((w,h))
 placements=[]
 for hh,ww in dims:
  for r in range(9-hh+1):
   for c in range(20-ww+1):
    cells=frozenset((r+dr,c+dc) for dr in range(hh) for dc in range(ww))
    if cells<=mask: placements.append(cells)
 return placements

def exact_solutions(allowrot=False, maxsol=1000):
 tileids=[]
 for name,h,w,n in shapes:
  for i in range(n): tileids.append((name,i))
 placements={tid:placements_for((tid[0],next(x[1] for x in shapes if x[0]==tid[0]),next(x[2] for x in shapes if x[0]==tid[0]),1),allowrot) for tid in tileids}
 bycell={cell:[] for cell in mask}
 for tid,pls in placements.items():
  for pi,p in enumerate(pls):
   for cell in p: bycell[cell].append((tid,pi,p))
 solutions=[]
 def rec(remaining,unused,chosen):
  if not remaining:
   if not unused: solutions.append(chosen.copy())
   return len(solutions)>=maxsol
  # cell with fewest currently valid candidate tile placements
  best=None; optsbest=None
  for cell in remaining:
   opts=[(tid,pi,p) for tid,pi,p in bycell[cell] if tid in unused and p<=remaining]
   if optsbest is None or len(opts)<len(optsbest): best,optsbest=cell,opts
   if len(optsbest)==0: return False
  for tid,pi,p in optsbest:
   remunused=unused-{tid}
   # prevent equivalent zero labels later? fine
   if rec(remaining-p,remunused,chosen+[(tid,p)]): return True
  return False
 rec(mask,set(tileids),[])
 return solutions
sol_no=exact_solutions(False,100)
len(sol_no),sol_no[:1]

for si,sol in enumerate(sol_no):
 print('SOL',si)
 # assign colors names
 g=[['.' if grid[r][c]==1 else '2' for c in range(20)] for r in range(9)]
 cols={'zero':'0','line5':'4','rect2x2':'7','rect2x3':'5','rect4x2':'3','checker4x6':'X','rect5x2':'6','rect5x3':'8'}
 for tid,p in sol:
  for r,c in p:g[r][c]=cols[tid[0]]
 print('\n'.join(''.join(x) for x in g))
 print({tid:(min(r for r,c in p),min(c for r,c in p),max(r for r,c in p),max(c for r,c in p)) for tid,p in sol})
